{
  "translations": {
    "L0001": "Demain, je reviendrai peut-être.",
    "L0002": "Sous la pluie, nous avons fait halte sous le pont.",
    "L0003": "Cette personne n’a pas promis de revenir.",
    "L0004": "Sur le papier, il y avait une image de l’esprit.",
    "L0005": "Je ne sais pas si c’était un souvenir ou un espoir.",
    "L0006": "Le mot inachevé, laisse-le inachevé."
  },
  "sourceNotes": []
}
